package com.cpurest.transport;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class HeaderLayoutTest {

    /**
     * These expected strings were generated by running the identical
     * algorithm through {@code cpurest_core::shm::shm_name} on the Rust
     * side (FNV-1a 32-bit over the trimmed bus name). If this test ever
     * fails, the two implementations have drifted and a Rust server and a
     * Java client will never be able to rendezvous on the same bus.
     */
    @Test
    void shmNameMatchesRustImplementation() {
        assertEquals("/cr_taxengine_12f89101", HeaderLayout.shmName("/tax_engine"));
        assertEquals("/cr_javabacken_72e4bb12", HeaderLayout.shmName("/java_backend"));
    }

    @Test
    void shmNameStaysUnderMacosLimit() {
        String name = HeaderLayout.shmName("/a_very_long_bus_name_that_keeps_going_and_going_12345");
        // macOS's PSHMNAMLEN is 31 bytes including the NUL terminator.
        assertTrue(name.getBytes(java.nio.charset.StandardCharsets.UTF_8).length < 31, "shm name too long: " + name);
    }

    @Test
    void layoutOffsetsMatchRust() {
        assertEquals(0, HeaderLayout.FLAG_OFFSET);
        assertEquals(64, HeaderLayout.METHOD_OFFSET);
        assertEquals(66, HeaderLayout.STATUS_OFFSET);
        assertEquals(68, HeaderLayout.LEN_OFFSET);
        assertEquals(128, HeaderLayout.ROUTE_OFFSET);
        assertEquals(192, HeaderLayout.HEADER_SIZE);
        assertEquals(512 * 1024, HeaderLayout.CHANNEL_SIZE);
        assertEquals(1024 * 1024, HeaderLayout.BUS_SIZE);
    }
}
